Here are some specific codes for using DLL injection in different programming languages:

### C/C++
```c
#include <windows.h>
#include <stdio.h>

int main() {
    HMODULE hMod;
    LPVOID pRemoteThread;
    HANDLE hThread;
    DWORD ThreadId;

    // Load the DLL
    hMod = LoadLibrary(TEXT("example.dll"));
    if (hMod == NULL) {
        printf("Failed to load the DLL.\n");
        return 1;
    }

    // Get the address of the function to inject
    FARPROC pFunc = GetProcAddress(hMod, "FunctionName");
    if (pFunc == NULL) {
        printf("Failed to get the function address.\n");
        FreeLibrary(hMod);
        return 1;
    }

    // Allocate memory for the DLL
    pRemoteThread = VirtualAllocEx(GetCurrentProcess(), NULL, 4096, MEM_COMMIT, PAGE_READWRITE);
    if (pRemoteThread == NULL) {
        printf("Failed to allocate memory for the DLL.\n");
        FreeLibrary(hMod);
        return 1;
    }

    // Write the DLL to the allocated memory
    WriteProcessMemory(GetCurrentProcess(), pRemoteThread, (LPVOID)pFunc, 4096, NULL);

    // Create a remote thread to execute the injected code
    hThread = CreateRemoteThread(GetCurrentProcess(), NULL, 0, (LPTHREAD_START_ROUTINE)pFunc, pRemoteThread, 0, &ThreadId);
    if (hThread == NULL) {
        printf("Failed to create the remote thread.\n");
        VirtualFreeEx(GetCurrentProcess(), pRemoteThread, 0, MEM_RELEASE);
        FreeLibrary(hMod);
        return 1;
    }

    // Wait for the remote thread to finish
    WaitForSingleObject(hThread, INFINITE);

    // Clean up
    CloseHandle(hThread);
    VirtualFreeEx(GetCurrentProcess(), pRemoteThread, 0, MEM_RELEASE);
    FreeLibrary(hMod);

    return 0;
}
```

